import java.sql.*;

/** 临时探针：探测云 PostgreSQL 的连通性、SSL 模式要求、以及已存在的数据库。 */
public class PgProbe {

    static final String HOST = "103.40.14.100";
    static final int PORT = 19476;
    static final String USER = "postgres";
    static final String PASS = "041014";

    public static void main(String[] args) {
        for (String mode : new String[]{"prefer", "require", "disable"}) {
            String url = "jdbc:postgresql://" + HOST + ":" + PORT + "/postgres"
                    + "?sslmode=" + mode + "&connectTimeout=10&socketTimeout=15";
            try (Connection c = DriverManager.getConnection(url, USER, PASS)) {
                DatabaseMetaData md = c.getMetaData();
                System.out.println("[OK] sslmode=" + mode);
                System.out.println("      server  : " + md.getDatabaseProductVersion());
                System.out.println("      driver  : " + md.getDriverVersion());
                try (Statement st = c.createStatement();
                     ResultSet rs = st.executeQuery(
                             "SELECT datname FROM pg_database WHERE datistemplate = false ORDER BY datname")) {
                    StringBuilder sb = new StringBuilder();
                    while (rs.next()) sb.append(rs.getString(1)).append("  ");
                    System.out.println("      已有库  : " + sb);
                }
                try (Statement st = c.createStatement();
                     ResultSet rs = st.executeQuery(
                             "SELECT current_user, current_setting('server_version_num')::int")) {
                    if (rs.next()) {
                        int ver = rs.getInt(2);
                        System.out.println("      当前用户: " + rs.getString(1)
                                + "   版本号: " + ver
                                + (ver >= 150000 ? "  (>=15, 支持 stringtype=unspecified 与 gen_random_uuid)" : ""));
                    }
                }
                try (Statement st = c.createStatement();
                     ResultSet rs = st.executeQuery("SELECT current_schema(), current_database()")) {
                    if (rs.next()) {
                        System.out.println("      schema  : " + rs.getString(1)
                                + "   当前库: " + rs.getString(2));
                    }
                }
                System.out.println("  ==> 推荐 URL: jdbc:postgresql://" + HOST + ":" + PORT + "/<库名>?sslmode=" + mode);
                return;
            } catch (SQLException e) {
                System.out.println("[FAIL] sslmode=" + mode + " -> " + e.getMessage());
            }
        }
    }
}

