"""纯本地静态检查器：不连接任何数据库，只解析 sql/ 下的脚本，交叉验证结构与引用一致性。"""
import re, sys, io
from collections import OrderedDict

SQL_DIR = r"C:\Users\lsy04\Documents\Project\volunteer-cert-portrait\sql"

def read(f):
    return io.open(SQL_DIR + "\\" + f, encoding="utf-8").read()

def strip_comments(s):
    # 去掉 -- 行注释（本工程脚本内没有字符串里含 -- 的情况）
    return "\n".join(re.sub(r"--.*$", "", line) for line in s.splitlines())

schema = strip_comments(read("02_schema.sql"))

# ---------- 1. 解析所有表及其列 ----------
tables = OrderedDict()
for m in re.finditer(r"CREATE TABLE\s+(\w+)\s*\((.*?)\n\)\s*;", schema, re.S):
    name, body = m.group(1), m.group(2)
    cols = []
    for line in body.splitlines():
        line = line.strip().rstrip(",")
        if not line:
            continue
        if re.match(r"(CONSTRAINT|PRIMARY KEY|UNIQUE|FOREIGN KEY|CHECK)\b", line, re.I):
            continue
        cm = re.match(r"(\w+)\s+", line)
        if cm:
            cols.append(cm.group(1))
    tables[name] = cols

print("=== 1. 表与列 ===")
print("表数量: %d" % len(tables))
for t, c in tables.items():
    print("  %-22s %2d 列" % (t, len(c)))

errors = []

# ---------- 2. 外键检查 ----------
print()
print("=== 2. 外键引用检查 ===")
fks = re.findall(
    r"CONSTRAINT\s+(\w+)\s+FOREIGN KEY\s*\((\w+)\)\s*REFERENCES\s+(\w+)\s*\((\w+)\)", schema)
print("外键数量: %d" % len(fks))
# 找出每个外键属于哪张表
owner = {}
for m in re.finditer(r"CREATE TABLE\s+(\w+)\s*\((.*?)\n\)\s*;", schema, re.S):
    for fm in re.finditer(r"CONSTRAINT\s+(\w+)\s+FOREIGN KEY", m.group(2)):
        owner[fm.group(1)] = m.group(1)

for cname, col, ref_tbl, ref_col in fks:
    t = owner.get(cname, "?")
    if ref_tbl not in tables:
        errors.append("外键 %s: 引用了不存在的表 %s" % (cname, ref_tbl))
    elif ref_col not in tables[ref_tbl]:
        errors.append("外键 %s: 表 %s 没有列 %s" % (cname, ref_tbl, ref_col))
    if t != "?" and col not in tables[t]:
        errors.append("外键 %s: 表 %s 没有列 %s" % (cname, t, col))
print("  %-26s %-22s -> %s(%s)" % ("约束名", "本表.列", "目标表", "目标列"))
for cname, col, ref_tbl, ref_col in fks:
    print("  %-26s %-22s -> %s(%s)" % (cname, owner.get(cname, "?") + "." + col, ref_tbl, ref_col))

# ---------- 3. 索引检查 ----------
print()
print("=== 3. 索引检查 ===")
idxs = re.findall(r"CREATE INDEX\s+(\w+)\s+ON\s+(\w+)\s*\(([^)]*)\)", schema)
print("索引数量: %d" % len(idxs))
for iname, itbl, icols in idxs:
    cols = [c.strip() for c in icols.split(",")]
    if itbl not in tables:
        errors.append("索引 %s: 表 %s 不存在" % (iname, itbl))
        continue
    for c in cols:
        if c not in tables[itbl]:
            errors.append("索引 %s: 表 %s 没有列 %s" % (iname, itbl, c))
    print("  %-30s %s(%s)" % (iname, itbl, ", ".join(cols)))

# ---------- 4. 唯一约束检查 ----------
print()
print("=== 4. 唯一约束检查 ===")
for m in re.finditer(r"CONSTRAINT\s+(\w+)\s+UNIQUE\s*\(([^)]*)\)", schema):
    cname, cols = m.group(1), [c.strip() for c in m.group(2).split(",")]
    t = owner.get(cname)
    print("  %-26s (%s)" % (cname, ", ".join(cols)))
    # 唯一约束归属表需另找
for m in re.finditer(r"CREATE TABLE\s+(\w+)\s*\((.*?)\n\)\s*;", schema, re.S):
    t, body = m.group(1), m.group(2)
    for um in re.finditer(r"CONSTRAINT\s+(\w+)\s+UNIQUE\s*\(([^)]*)\)", body):
        for c in [x.strip() for x in um.group(2).split(",")]:
            if c not in tables[t]:
                errors.append("唯一约束 %s: 表 %s 没有列 %s" % (um.group(1), t, c))
    # 列级 UNIQUE
    for line in body.splitlines():
        if re.search(r"\bUNIQUE\b", line) and not line.strip().startswith("CONSTRAINT"):
            cm = re.match(r"\s*(\w+)\s", line)
            if cm and cm.group(1) not in tables[t]:
                errors.append("列级 UNIQUE: 表 %s 没有列 %s" % (t, cm.group(1)))

# ---------- 5. INSERT 列名检查 ----------
print()
print("=== 5. 数据脚本 INSERT 列名检查 ===")
for f in ["03_init_data.sql", "04_demo_data.sql"]:
    src = strip_comments(read(f))
    for m in re.finditer(r"INSERT INTO\s+(\w+)\s*\(([^)]*)\)", src):
        t, cols = m.group(1), [c.strip() for c in m.group(2).split(",")]
        if t not in tables:
            errors.append("%s: INSERT 到不存在的表 %s" % (f, t))
            continue
        for c in cols:
            if c not in tables[t]:
                errors.append("%s: INSERT INTO %s 的列 %s 不存在" % (f, t, c))
    # 无列名的 INSERT（INSERT INTO t SELECT ...）跳过
    print("  %s: 已检查 %d 条带列名的 INSERT" % (
        f, len(re.findall(r"INSERT INTO\s+\w+\s*\(", src))))

# ---------- 6. setval 目标检查 ----------
print()
print("=== 6. setval 目标表检查 ===")
for f in ["03_init_data.sql", "04_demo_data.sql"]:
    src = read(f)
    for m in re.finditer(r"pg_get_serial_sequence\('(\w+)'", src):
        t = m.group(1)
        if t not in tables:
            errors.append("%s: setval 引用了不存在的表 %s" % (f, t))
    print("  %s: setval 引用 %d 处，目标表均存在: %s" % (
        f, len(re.findall(r"pg_get_serial_sequence", src)),
        all(t in tables for t in re.findall(r"pg_get_serial_sequence\('(\w+)'", src))))

# ---------- 7. DROP 表清单与 CREATE 清单一致性 ----------
print()
print("=== 7. DROP 与 CREATE 清单一致性 ===")
dropped = set(re.findall(r"DROP TABLE IF EXISTS\s+(\w+)", schema))
created = set(tables)
if dropped == created:
    print("  OK: DROP 清单与 CREATE 清单完全一致（各 %d 张）" % len(created))
else:
    print("  仅 DROP 未 CREATE: %s" % (dropped - created))
    print("  仅 CREATE 未 DROP: %s" % (created - dropped))
    errors.append("DROP/CREATE 清单不一致")

# ---------- 8. 字典覆盖检查 ----------
print()
print("=== 8. 状态枚举是否都有字典覆盖 ===")
init = read("03_init_data.sql")
dict_types = set(re.findall(r"\('(\w+)',\s*'[A-Z_]+',", init))
print("  已初始化字典类型: %s" % ", ".join(sorted(dict_types)))
enum_checks = {
    "activity_status":   (r"status\s+VARCHAR\(20\)\s+DEFAULT\s+'(\w+)'", "volunteer_activity"),
    "signup_status":     (r"status\s+VARCHAR\(20\)\s+DEFAULT\s+'(\w+)'", "activity_signup"),
    "attendance_status": (r"status\s+VARCHAR\(20\)\s+DEFAULT\s+'(\w+)'", "attendance_record"),
    "duration_status":   (r"status\s+VARCHAR\(20\)\s+DEFAULT\s+'(\w+)'", "service_duration"),
}
for dt in ["activity_status", "signup_status", "attendance_status", "duration_status",
           "org_status", "notification_type", "audit_action", "attachment_biz_type"]:
    print("  %-20s %s" % (dt, "已覆盖" if dt in dict_types else "缺失"))

# ---------- 结论 ----------
print()
print("=" * 60)
if errors:
    print("发现 %d 个问题：" % len(errors))
    for e in errors:
        print("  [!] " + e)
    sys.exit(1)
else:
