import java.nio.file.Files;
import java.nio.file.Paths;
import java.sql.*;

/**
 * 临时脚本执行器（用户已授权）：在云 PostgreSQL 上建库并依次执行 sql/ 下的脚本。
 * 安全检查：目标库若已存在且含表，立即中止，绝不覆盖已有数据。
 */
public class RunSql {

    static final String HOST = "103.40.14.100";
    static final int PORT = 19476;
    static final String USER = "postgres";
    static final String PASS = "041014";
    static final String DB = "volunteer_cert_portrait";
    static final String SQL_DIR = "C:/Users/lsy04/Documents/Project/volunteer-cert-portrait/sql";

    public static void main(String[] args) throws Exception {

        // ---------- 1. 连 postgres 库，检查目标库是否存在 ----------
        String adminUrl = "jdbc:postgresql://" + HOST + ":" + PORT
                + "/postgres?sslmode=prefer&connectTimeout=15&socketTimeout=60";

        try (Connection c = DriverManager.getConnection(adminUrl, USER, PASS)) {
            System.out.println("[连接成功] " + c.getMetaData().getDatabaseProductVersion());
            System.out.println("[SSL] " + c.getMetaData().getURL());

            boolean exists;
            try (Statement st = c.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT 1 FROM pg_database WHERE datname = '" + DB + "'")) {
                exists = rs.next();
            }
            System.out.println("[检查] 目标库 " + DB + " 是否已存在: " + exists);

            if (!exists) {
                try (Statement st = c.createStatement()) {
                    st.execute("CREATE DATABASE " + DB
                            + " WITH OWNER = " + USER + " ENCODING = 'UTF8' TEMPLATE = template0");
                }
                System.out.println("[建库] 已创建数据库 " + DB);
            }
        }

        // ---------- 2. 连目标库 ----------
        String dbUrl = "jdbc:postgresql://" + HOST + ":" + PORT + "/" + DB
                + "?sslmode=prefer&connectTimeout=15&socketTimeout=180";

        try (Connection c = DriverManager.getConnection(dbUrl, USER, PASS)) {

            int existing;
            try (Statement st = c.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT count(*) FROM information_schema.tables "
                       + "WHERE table_schema = 'public' AND table_type = 'BASE TABLE'")) {
                rs.next();
                existing = rs.getInt(1);
            }
            System.out.println("[检查] 目标库现有业务表数量: " + existing);

            if (existing > 0) {
                System.out.println("!! 目标库非空，为避免破坏已有数据已中止。");
                return;
            }

            // ---------- 3. 依次执行脚本 ----------
            for (String f : new String[]{"02_schema.sql", "03_init_data.sql", "04_demo_data.sql"}) {
                String sql = new String(
                        Files.readAllBytes(Paths.get(SQL_DIR, f)), StandardCharsets.UTF_8);
                System.out.println("--- 执行 " + f + " (" + sql.length() + " 字符) ---");
                try (Statement st = c.createStatement()) {
                    st.execute(sql);
                }
                System.out.println("    成功");
            }

            // ---------- 4. 行数 ----------
            System.out.println();
            System.out.println("=== 各表行数 ===");
            String[] tables = {"sys_user", "sys_role", "sys_user_role", "student_info", "org_info",
                    "activity_category", "volunteer_activity", "activity_signup",
                    "attendance_record", "service_duration", "duration_audit",
                    "student_profile", "notification", "sys_dict", "operation_log", "attachment"};
            int total = 0;
            for (String t : tables) {
                try (Statement st = c.createStatement();
                     ResultSet rs = st.executeQuery("SELECT count(*) FROM " + t)) {
                    rs.next();
                    int n = rs.getInt(1);
                    total += n;
                    System.out.printf("  %-22s %5d%n", t, n);
                }
            }
            System.out.println("  ------------------------------");
            System.out.printf("  %-22s %5d%n", "合计", total);

            // ---------- 5. 状态分布 ----------
            System.out.println();
            System.out.println("=== 状态分布 ===");
            String[][] checks = {
                {"活动状态", "SELECT status, count(*) FROM volunteer_activity GROUP BY status ORDER BY status"},
                {"报名状态", "SELECT status, count(*) FROM activity_signup GROUP BY status ORDER BY status"},
                {"签到状态", "SELECT status, count(*) FROM attendance_record GROUP BY status ORDER BY status"},
                {"时长状态", "SELECT status, count(*) FROM service_duration GROUP BY status ORDER BY status"},
            };
            for (String[] ck : checks) {
                System.out.println("  " + ck[0] + ":");
                try (Statement st = c.createStatement(); ResultSet rs = st.executeQuery(ck[1])) {
                    while (rs.next()) {
                        System.out.printf("      %-16s %4d%n", rs.getString(1), rs.getInt(2));
                    }
                }
            }

            // ---------- 6. 一致性自检 ----------
            System.out.println();
            System.out.println("=== 一致性自检（期望全部为 0）===");
            String[][] integrity = {
                {"时长的 signup_id 悬空", "SELECT count(*) FROM service_duration sd LEFT JOIN activity_signup sg ON sg.id = sd.signup_id WHERE sg.id IS NULL"},
                {"已完成的报名缺签到记录", "SELECT count(*) FROM activity_signup sg WHERE sg.status = 'COMPLETED' AND NOT EXISTS (SELECT 1 FROM attendance_record ar WHERE ar.signup_id = sg.id)"},
                {"学生累计时长与明细不符", "SELECT count(*) FROM student_info si WHERE si.total_duration <> COALESCE((SELECT SUM(sd.duration) FROM service_duration sd WHERE sd.student_id = si.id AND sd.status = 'APPROVED'), 0)"},
                {"活动报名计数与明细不符", "SELECT count(*) FROM volunteer_activity va WHERE va.signed_count <> (SELECT count(*) FROM activity_signup sg WHERE sg.activity_id = va.id AND sg.status IN ('APPROVED','COMPLETED'))"},
                {"画像的 student_id 悬空", "SELECT count(*) FROM student_profile sp LEFT JOIN student_info si ON si.id = sp.student_id WHERE si.id IS NULL"},
                {"缺勤却有时长记录", "SELECT count(*) FROM service_duration sd JOIN attendance_record ar ON ar.signup_id = sd.signup_id WHERE ar.status = 'ABSENT'"},
                {"待审核的时长却有审核人", "SELECT count(*) FROM service_duration WHERE status = 'PENDING_AUDIT' AND audit_user_id IS NOT NULL"},
                {"待审核的报名却有审核人", "SELECT count(*) FROM activity_signup WHERE status = 'PENDING' AND audit_user_id IS NOT NULL"},
                {"已完成的报名缺审核人", "SELECT count(*) FROM activity_signup WHERE status = 'COMPLETED' AND audit_user_id IS NULL"},
                {"取消的报名却填了驳回意见", "SELECT count(*) FROM activity_signup WHERE status = 'CANCELED' AND audit_remark IS NOT NULL"},
                {"时长超过活动预计时长", "SELECT count(*) FROM service_duration sd JOIN volunteer_activity va ON va.id = sd.activity_id WHERE sd.duration > va.duration"},
                {"有画像但无学生", "SELECT count(*) FROM student_profile sp WHERE NOT EXISTS (SELECT 1 FROM student_info si WHERE si.id = sp.student_id)"},
            };
            for (String[] q : integrity) {
                try (Statement st = c.createStatement(); ResultSet rs = st.executeQuery(q[1])) {
                    rs.next();
                    int n = rs.getInt(1);
                    System.out.printf("  %-30s %4d  %s%n", q[0], n, n == 0 ? "OK" : "<== 异常");
                }
            }

            // ---------- 7. 看板聚合 ----------
            System.out.println();
            System.out.println("=== 看板：各学院累计有效志愿时长排名 ===");
            try (Statement st = c.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT si.college, ROUND(SUM(sd.duration), 1) AS total_hours, "
                       + "       COUNT(DISTINCT si.id) AS students "
                       + "FROM service_duration sd JOIN student_info si ON si.id = sd.student_id "
                       + "WHERE sd.status = 'APPROVED' "
                       + "GROUP BY si.college ORDER BY total_hours DESC")) {
                while (rs.next()) {
                    System.out.printf("  %-16s %8s 小时  %3d 人%n",
                            rs.getString(1), rs.getString(2), rs.getInt(3));
                }
            }

            // ---------- 8. 看板概览 ----------
            System.out.println();
            System.out.println("=== 看板：概览指标 ===");
            String[][] kpi = {
                {"活动总数", "SELECT count(*) FROM volunteer_activity WHERE deleted = 0"},
                {"报名总人数", "SELECT count(*) FROM activity_signup WHERE deleted = 0"},
                {"累计志愿时长", "SELECT COALESCE(SUM(duration),0) FROM service_duration WHERE status='APPROVED' AND deleted=0"},
                {"本月新增活动数", "SELECT count(*) FROM volunteer_activity WHERE deleted=0 AND create_time >= date_trunc('month', CURRENT_TIMESTAMP)"},
                {"签到率", "SELECT ROUND(100.0 * count(*) FILTER (WHERE status IN ('SIGNED_OUT','ABNORMAL')) / NULLIF(count(*),0), 1) || '%' FROM attendance_record WHERE deleted=0"},
                {"时长审核通过率", "SELECT ROUND(100.0 * count(*) FILTER (WHERE status='APPROVED') / NULLIF(count(*) FILTER (WHERE status IN ('APPROVED','REJECTED')),0), 1) || '%' FROM service_duration WHERE deleted=0"},
                {"公益标签分布", "SELECT tags FROM student_profile WHERE tags <> '' LIMIT 3"},
            };
            for (String[] k : kpi) {
                try (Statement st = c.createStatement(); ResultSet rs = st.executeQuery(k[1])) {
                    while (rs.next()) {
                        System.out.printf("  %-16s %s%n", k[0], rs.getString(1));
                    }
                }
            }

            // ---------- 9. 抽一个学生看完整闭环 ----------
            System.out.println();
            System.out.println("=== 抽样：学生档案 id=2 的闭环数据 ===");
            try (Statement st = c.createStatement();
                 ResultSet rs = st.executeQuery(
                         "SELECT si.student_no, si.college, si.total_duration, si.public_welfare_level, "
                       + "       sp.total_activities, sp.category_preference, sp.tags "
                       + "FROM student_info si LEFT JOIN student_profile sp ON sp.student_id = si.id "
                       + "WHERE si.id = 2")) {
                while (rs.next()) {
                    System.out.printf("  学号=%s 学院=%s%n", rs.getString(1), rs.getString(2));
                    System.out.printf("  累计时长=%s 等级=%s%n", rs.getString(3), rs.getString(4));
                    System.out.printf("  活动次数=%s 偏好=%s%n", rs.getString(5), rs.getString(6));
                    System.out.printf("  标签=%s%n", rs.getString(7));
                }
            }
        }
    }
}

