import java.sql.*;

/** 只读查询：为公益等级/标签阈值定档提供真实数据分布。 */
public class Query {

    static final String HOST = "103.40.14.100";
    static final int PORT = 19476;
    static final String USER = "postgres";
    static final String PASS = "041014";
    static final String DB = "volunteer_cert_portrait";

    public static void main(String[] args) throws Exception {
        String url = "jdbc:postgresql://" + HOST + ":" + PORT + "/" + DB
                + "?sslmode=prefer&connectTimeout=15&socketTimeout=60";
        try (Connection c = DriverManager.getConnection(url, USER, PASS)) {

            q(c, "学生累计有效时长：分布明细",
              "SELECT si.total_duration AS 时长, COUNT(*) AS 人数 "
            + "FROM student_info si GROUP BY si.total_duration ORDER BY si.total_duration");

            q(c, "学生累计有效时长：汇总",
              "SELECT MIN(total_duration) AS 最小, ROUND(AVG(total_duration),1) AS 平均, "
            + "MAX(total_duration) AS 最大, COUNT(*) AS 人数 FROM student_info");

            q(c, "每学生已完成活动次数：分布",
              "SELECT cnt AS 完成次数, COUNT(*) AS 人数 FROM ("
            + "  SELECT sg.student_id, COUNT(DISTINCT sg.activity_id) AS cnt "
            + "  FROM activity_signup sg WHERE sg.status='COMPLETED' "
            + "  GROUP BY sg.student_id) t GROUP BY cnt ORDER BY cnt");

            q(c, "已完成的报名：按活动分类",
              "SELECT ac.category_name AS 分类, COUNT(*) AS 人次, COUNT(DISTINCT sg.student_id) AS 人数 "
            + "FROM activity_signup sg JOIN volunteer_activity a ON a.id = sg.activity_id "
            + "JOIN activity_category ac ON ac.id = a.category_id "
            + "WHERE sg.status='COMPLETED' GROUP BY ac.category_name ORDER BY 2 DESC");

            q(c, "每学生在同一分类下的参与次数（用于判断类型标签阈值）",
              "SELECT cnt AS 同分类参与次数, COUNT(*) AS 学生数 FROM ("
            + "  SELECT sg.student_id, a.category_id, COUNT(*) AS cnt "
            + "  FROM activity_signup sg JOIN volunteer_activity a ON a.id = sg.activity_id "
            + "  WHERE sg.status='COMPLETED' GROUP BY sg.student_id, a.category_id) t "
            + "GROUP BY cnt ORDER BY cnt");

            q(c, "按累计时长分 8 档（0~80 小时，每档 10 小时）的人数",
              "SELECT width_bucket(total_duration, 0, 80, 8) AS 档位, "
            + "       COUNT(*) AS 人数, MIN(total_duration) AS 档内最小, MAX(total_duration) AS 档内最大 "
            + "FROM student_info GROUP BY 档位 ORDER BY 档位");

            q(c, "参与跨度的学生数（首末次活动间隔天数 >= 30 的人数）",
              "SELECT COUNT(*) AS 跨度超30天的学生数 FROM ("
            + "  SELECT sg.student_id, MAX(a.end_time) - MIN(a.start_time) AS span "
            + "  FROM activity_signup sg JOIN volunteer_activity a ON a.id = sg.activity_id "
            + "  WHERE sg.status='COMPLETED' GROUP BY sg.student_id) t WHERE span >= INTERVAL '30 days'");
        }
    }

    static void q(Connection c, String title, String sql) throws SQLException {
        System.out.println("=== " + title + " ===");
        try (Statement st = c.createStatement(); ResultSet rs = st.executeQuery(sql)) {
            ResultSetMetaData md = rs.getMetaData();
            int n = md.getColumnCount();
            StringBuilder head = new StringBuilder("  ");
            for (int i = 1; i <= n; i++) {
                head.append(String.format("%-14s", md.getColumnLabel(i)));
            }
            System.out.println(head);
            while (rs.next()) {
                StringBuilder row = new StringBuilder("  ");
                for (int i = 1; i <= n; i++) {
                    row.append(String.format("%-14s", rs.getString(i)));
                }
                System.out.println(row);
            }
        }
        System.out.println();
    }
}

